#include "script_workspace.hpp"
#include <iostream>
using namespace worlded;

class ScriptWindow : public QMainWindow {
    QTabWidget* documents=new QTabWidget;
    QListWidget* library=new QListWidget;
    QLineEdit* search=new QLineEdit;
    std::shared_ptr<Installation> installation;
    QString rootPath;
    struct Document {QString path;QString name;ScriptWorkspace* script=nullptr;DialogueEditor* dialogue=nullptr;bool dirty=false;};
    std::map<QWidget*,Document> open;
    QMap<unsigned,QString> conditions,actions;
    Document* current(){auto it=open.find(documents->currentWidget());return it==open.end()?nullptr:&it->second;}
    void error(const std::exception& e){QMessageBox::warning(this,"Script editor",QString::fromUtf8(e.what()));}
    void changed(QWidget* widget){auto& d=open.at(widget);d.dirty=true;documents->setTabText(documents->indexOf(widget),d.name+" *");}
    bool discard(Document& d){return !d.dirty || QMessageBox::question(this,"Unsaved changes","Discard changes to "+d.name+"?")==QMessageBox::Yes;}
    QMap<QString,int> companionLabels(const Document& d){
        QString stem=QFileInfo(d.path).completeBaseName();for(auto& pair:open){auto& candidate=pair.second;if(candidate.script && candidate.script->modern() && QFileInfo(candidate.path).completeBaseName()==stem)return candidate.script->compile().labels;}
        QStringList paths={QFileInfo(d.path).dir().filePath(stem+".wscript"),rootPath+"/script-sources/"+stem+".wscript"};
        for(auto path:paths)if(QFileInfo::exists(path)){auto bytes=script_read_file(path);return compile_modern_script(QString::fromUtf8(reinterpret_cast<const char*>(bytes.data()),int(bytes.size()))).labels;}
        return {};
    }
    void labels(){conditions.clear();actions.clear();if(!installation)return;for(bool condition:{true,false})try{for(const auto& entry:read_messages(installation->read(condition?"semes/condition.mes":"semes/action.mes")))(condition?conditions:actions)[entry.id]=QString::fromStdString(cp1252_utf8(entry.text));}catch(const std::exception&){}for(auto& pair:open)if(pair.second.script)pair.second.script->refreshLabels();}
public:
    ScriptWindow(){setWindowTitle("Script Editor Renaissance");resize(1240,820);setCentralWidget(documents);documents->setTabsClosable(true);
        auto dock=new QDockWidget("Scripts and dialogues",this);auto browser=new QWidget;auto layout=new QVBoxLayout(browser);search->setPlaceholderText("Filter by ID or name");layout->addWidget(search);layout->addWidget(library);dock->setWidget(browser);addDockWidget(Qt::LeftDockWidgetArea,dock);
        auto action=[&](QMenu* menu,const QString& title,const QKeySequence& shortcut,const std::function<void()>& fn){auto a=menu->addAction(title);a->setShortcut(shortcut);connect(a,&QAction::triggered,this,[this,fn]{try{fn();}catch(const std::exception& e){error(e);}});return a;};
        auto file=menuBar()->addMenu("File");action(file,"New structured script",QKeySequence::New,[this]{add("untitled.wscript",{},true);});action(file,"New native script",{},[this]{add("untitled.scr",empty_script(),true);});action(file,"New dialogue",{},[this]{add("untitled.wdlg",dialogue_source(new_dialogue()),true);});action(file,"Open…",QKeySequence::Open,[this]{auto path=QFileDialog::getOpenFileName(this,"Open script or dialogue",rootPath,"Scripts and dialogues (*.scr *.wscript *.dlg *.wdlg)");if(!path.isEmpty())openFile(path);});
        action(file,"Open project folder…",{},[this]{auto path=QFileDialog::getExistingDirectory(this,"Project folder",rootPath);if(!path.isEmpty())openProject(path);});action(file,"Choose Arcanum installation…",{},[this]{auto path=QFileDialog::getExistingDirectory(this,"Arcanum installation");if(!path.isEmpty())setInstallation(path);});file->addSeparator();action(file,"Save",QKeySequence::Save,[this]{save(false);});action(file,"Save as…",QKeySequence::SaveAs,[this]{save(true);});action(file,"Export compiled file…",QKeySequence("Ctrl+Shift+B"),[this]{exportCurrent();});file->addSeparator();action(file,"Close tab",QKeySequence::Close,[this]{closeTab(documents->currentIndex());});action(file,"Quit",QKeySequence::Quit,[this]{close();});
        auto build=menuBar()->addMenu("Script");action(build,"Build project…",QKeySequence("Ctrl+F7"),[this]{if(rootPath.isEmpty())throw std::runtime_error("Open a project folder first");for(const auto& item:open)if(item.second.dirty)throw std::runtime_error("Save all open documents before building the project");auto result=compile_script_project(rootPath);auto target=QFileDialog::getExistingDirectory(this,"Choose an empty export folder");if(target.isEmpty())return;export_script_project(target,result);statusBar()->showMessage(QString("Built %1 resources in %2").arg(result.files.size()).arg(target));});action(build,"Compile / validate",QKeySequence("F7"),[this]{validate();});action(build,"Properties",{},[this]{if(auto d=current();d && d->script)d->script->editProperties();});action(build,"Open companion…",{},[this]{auto d=current();if(!d)return;auto stem=QFileInfo(d->path).completeBaseName();QStringList candidates;for(const auto& suffix:d->script?QStringList{".wdlg",".dlg"}:QStringList{".wscript",".scr"}){candidates<<QFileInfo(d->path).dir().filePath(stem+suffix)<<rootPath+"/script-sources/"+stem+suffix<<rootPath+"/exports/"+(d->script?"dlg/":"scr/")+stem+suffix;}for(auto path:candidates)if(QFileInfo::exists(path)){openFile(path);return;}throw std::runtime_error("No companion file found in this folder or project");});
        auto edit=menuBar()->addMenu("Edit");action(edit,"Undo",QKeySequence::Undo,[this]{if(auto d=current();d && d->script){if(d->script->modern())d->script->editor->undo();else d->script->nativeEditor()->undoStack()->undo();}});action(edit,"Redo",QKeySequence::Redo,[this]{if(auto d=current();d && d->script){if(d->script->modern())d->script->editor->redo();else d->script->nativeEditor()->undoStack()->redo();}});
        auto help=menuBar()->addMenu("Help");action(help,"Script editing guide",{},[this]{auto path=QCoreApplication::applicationDirPath()+"/script-editor.html";if(QFileInfo::exists(path))QDesktopServices::openUrl(QUrl::fromLocalFile(path));else QMessageBox::information(this,"Script editing","Create scripts with File > New structured script. F7 compiles and validates. Native SCR files open as editable instructions. Save keeps the source; Export writes the game resource. Read docs/script-editor.md in the source repository.");});
        connect(search,&QLineEdit::textChanged,this,[this]{refreshLibrary();});connect(library,&QListWidget::itemDoubleClicked,this,[this](QListWidgetItem* item){try{auto path=item->data(Qt::UserRole).toString();if(item->data(Qt::UserRole+1).toBool())add(path,installation->read(path.toStdString()),false,true);else openFile(path);}catch(const std::exception& e){error(e);}});connect(documents,&QTabWidget::tabCloseRequested,this,[this](int i){closeTab(i);});statusBar()->showMessage("Open a script or a project folder. No map is required.");
        auto previous=QSettings("ArcanumRenaissance","ScriptEditor").value("installation").toString();if(!previous.isEmpty())try{setInstallation(previous);}catch(const std::exception&){}
    }
    void setInstallation(const QString& path){auto next=std::make_shared<Installation>(std::filesystem::u8path(path.toUtf8().constData()));installation=std::move(next);QSettings("ArcanumRenaissance","ScriptEditor").setValue("installation",path);labels();refreshLibrary();}
    void openProject(const QString& path){rootPath=QDir(path).absolutePath();refreshLibrary();}
    void refreshLibrary(){library->clear();if(!rootPath.isEmpty()){QDirIterator it(rootPath,{"*.scr","*.wscript","*.dlg","*.wdlg"},QDir::Files,QDirIterator::Subdirectories);while(it.hasNext()){auto path=it.next();auto name=QDir(rootPath).relativeFilePath(path);if(!name.contains(search->text(),Qt::CaseInsensitive))continue;auto item=new QListWidgetItem(name,library);item->setData(Qt::UserRole,path);}}if(installation)for(const auto& entry:installation->resources()){auto path=QString::fromStdString(entry.first);if((path.endsWith(".scr") || path.endsWith(".dlg")) && path.contains(search->text(),Qt::CaseInsensitive)){auto item=new QListWidgetItem("Game: "+path,library);item->setData(Qt::UserRole,path);item->setData(Qt::UserRole+1,true);}}}
    void openFile(const QString& path){QString absolute=QFileInfo(path).absoluteFilePath();for(auto& pair:open)if(pair.second.path==absolute){documents->setCurrentWidget(pair.first);return;}add(absolute,script_read_file(absolute));}
    void add(const QString& path,const Bytes& bytes,bool fresh=false,bool fromGame=false){
        bool modern=path.endsWith(".wscript",Qt::CaseInsensitive),dialogue=path.endsWith(".dlg",Qt::CaseInsensitive)||path.endsWith(".wdlg",Qt::CaseInsensitive);QWidget* widget;Document doc;doc.path=fresh||fromGame?QString{}:path;doc.name=QFileInfo(path).fileName();doc.dirty=fresh||fromGame;
        if(dialogue){doc.dialogue=new DialogueEditor;doc.dialogue->load(path.endsWith(".wdlg",Qt::CaseInsensitive)?read_dialogue_source(bytes):parse_dialogue(bytes));widget=doc.dialogue;doc.dialogue->changed=[this,widget]{changed(widget);};doc.dialogue->resolveTargets=[this,widget](Dialogue value){return resolve_dialogue(std::move(value),companionLabels(open.at(widget)));};}
        else{Bytes binary=modern?empty_script():bytes;auto compiled=QFileInfo(path).dir().filePath(QFileInfo(path).completeBaseName()+".scr");if(modern && !QFileInfo::exists(compiled) && !rootPath.isEmpty())compiled=rootPath+"/exports/scr/"+QFileInfo(path).completeBaseName()+".scr";if(modern && QFileInfo::exists(compiled))binary=script_read_file(compiled);doc.script=new ScriptWorkspace(binary,modern,modern?(fresh?"// Write your script here.\nreturn;\n":QString::fromUtf8(reinterpret_cast<const char*>(bytes.data()),int(bytes.size()))):QString{});widget=doc.script;doc.script->operationLabel=[this](unsigned id,bool condition){return (condition?conditions:actions).value(id);};doc.script->refreshLabels();doc.script->changed=[this,widget]{changed(widget);};}
        open[widget]=doc;documents->addTab(widget,doc.name+(doc.dirty?" *":""));documents->setCurrentWidget(widget);
    }
    void validate(){auto d=current();if(!d)return;if(d->script){auto compiled=d->script->compile();auto warnings=script_warnings(compiled.bytes);statusBar()->showMessage(warnings.isEmpty()?"Script compiled successfully":warnings.join("; "));}else{auto resolved=resolve_dialogue(d->dialogue->value(),companionLabels(*d));auto warnings=validate_dialogue(resolved);statusBar()->showMessage(warnings.isEmpty()?"Dialogue validated":warnings.join("; "));}}
    void save(bool choose){auto d=current();if(!d)return;auto widget=documents->currentWidget();auto path=d->path;if(choose || path.isEmpty()){path=QFileDialog::getSaveFileName(this,"Save source",path.isEmpty()?QDir(rootPath).filePath(d->name):path,d->script?(d->script->modern()?"Structured script (*.wscript)":"Native script (*.scr)"):"Dialogue source (*.wdlg);;Native dialogue (*.dlg)");if(path.isEmpty())return;}
        Bytes bytes;if(d->script){if(d->script->modern()){if(!path.endsWith(".wscript",Qt::CaseInsensitive))path+=".wscript";auto result=d->script->compile();auto text=d->script->editor->toPlainText().toUtf8();bytes=Bytes(text.begin(),text.end());auto companion=QFileInfo(path).dir().filePath(QFileInfo(path).completeBaseName()+".scr");if(QFileInfo::exists(companion) && companion!=QFileInfo(d->path).dir().filePath(QFileInfo(d->path).completeBaseName()+".scr") && QMessageBox::question(this,"Existing compiled script","Replace "+companion+"?")!=QMessageBox::Yes)return;script_write_file(companion,result.bytes);}else{if(!path.endsWith(".scr",Qt::CaseInsensitive))path+=".scr";bytes=d->script->compile().bytes;}}
        else{if(path.endsWith(".dlg",Qt::CaseInsensitive)){bool symbolic=false;for(const auto& row:d->dialogue->value())symbolic|=row.fields[5].trimmed().startsWith('@');if(symbolic){auto sourcePath=QFileInfo(path).dir().filePath(QFileInfo(path).completeBaseName()+".wdlg");path=QFileDialog::getSaveFileName(this,"Keep named destinations in a dialogue source",sourcePath,"Dialogue source (*.wdlg)");if(path.isEmpty())return;if(!path.endsWith(".wdlg",Qt::CaseInsensitive))path+=".wdlg";}}if(!path.endsWith(".dlg",Qt::CaseInsensitive) && !path.endsWith(".wdlg",Qt::CaseInsensitive))path+=".wdlg";bytes=path.endsWith(".wdlg",Qt::CaseInsensitive)?dialogue_source(d->dialogue->value()):encode_dialogue(resolve_dialogue(d->dialogue->value(),companionLabels(*d)));}
        script_write_file(path,bytes);d->path=QFileInfo(path).absoluteFilePath();d->name=QFileInfo(path).fileName();d->dirty=false;documents->setTabText(documents->indexOf(widget),d->name);refreshLibrary();statusBar()->showMessage("Saved "+path);
    }
    void exportCurrent(){auto d=current();if(!d)return;Bytes bytes=d->script?d->script->compile().bytes:encode_dialogue(resolve_dialogue(d->dialogue->value(),companionLabels(*d)));auto path=QFileDialog::getSaveFileName(this,"Export game resource",QDir(rootPath).filePath(QFileInfo(d->name).completeBaseName()+(d->script?".scr":".dlg")),d->script?"Native script (*.scr)":"Native dialogue (*.dlg)");if(path.isEmpty())return;script_write_file(path,bytes);statusBar()->showMessage("Exported "+path+". Keep the source with your project.");}
    void closeTab(int index){auto widget=documents->widget(index);if(!widget)return;auto& d=open.at(widget);if(!discard(d))return;open.erase(widget);documents->removeTab(index);widget->deleteLater();}
protected:
    void closeEvent(QCloseEvent* event)override{for(auto& pair:open)if(!discard(pair.second)){event->ignore();return;}event->accept();}
};
int main(int argc,char** argv){
    // CLI compilation uses the same compiler and never needs a display server.
    if(argc>1 && (QString::fromLocal8Bit(argv[1])=="--compile" || QString::fromLocal8Bit(argv[1])=="--compile-project" || QString::fromLocal8Bit(argv[1])=="--validate" || QString::fromLocal8Bit(argv[1])=="--help")){
        QCoreApplication app(argc,argv);auto args=app.arguments();if(args[1]=="--help"){std::cout<<"Script Editor Renaissance\n  script-editor [FILE] [--project DIR] [--game DIR]\n  script-editor --compile SOURCE.wscript --output FILE.scr\n  script-editor --compile-project PROJECT --output EMPTY_DIRECTORY\n  script-editor --validate FILE.scr\n";return 0;}
        try{if(args.size()<3)throw std::runtime_error("Input file required");if(args[1]=="--compile-project"){int output=args.indexOf("--output");if(output<0 || output+1>=args.size())throw std::runtime_error("--output EMPTY_DIRECTORY is required");auto result=compile_script_project(args[2]);export_script_project(args[output+1],result);std::cout<<result.files.size()<<" resources built\n";return 0;}auto bytes=script_read_file(args[2]);if(args[1]=="--validate"){inspect_script(bytes);auto warnings=script_warnings(bytes);for(auto text:warnings)std::cout<<text.toStdString()<<'\n';}else{int output=args.indexOf("--output");if(output<0 || output+1>=args.size())throw std::runtime_error("--output FILE.scr is required");auto result=compile_modern_script(QString::fromUtf8(reinterpret_cast<const char*>(bytes.data()),int(bytes.size())));script_write_file(args[output+1],result.bytes);}return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}
    }
    QApplication app(argc,argv);QApplication::setApplicationName("Script Editor Renaissance");if(app.arguments().contains("--smoke-test")){ScriptWorkspace smoke(empty_script(),true,"return;");smoke.resize(800,600);smoke.show();app.processEvents();smoke.compile();return 0;}ScriptWindow window;auto args=app.arguments();try{for(int i=1;i<args.size();++i){if(args[i]=="--project" || args[i]=="--game"){auto key=args[i];if(++i>=args.size())throw std::runtime_error("Missing path");if(key=="--project")window.openProject(args[i]);else window.setInstallation(args[i]);}else window.openFile(args[i]);}}catch(const std::exception& e){QMessageBox::warning(&window,"Cannot open",e.what());}window.show();return app.exec();
}
